#!/usr/bin/env python3
"""Embed the reviewed GLSL sources; no runtime filesystem or shader compiler tool needed."""
from pathlib import Path

root = Path(__file__).resolve().parents[2] / "src" / "hd"
for module in ("map_lighting", "map_post"):
    source = (root / "shaders" / (module + ".glsl")).read_text()
    (root / (module + "_shader.h")).write_text(
        "// Generated by tools/hd/embed_shaders.py; edit shaders/*.glsl.\n"
        "// Ported from Dustlight c1752ecc; see docs/DUSTLIGHT-NOTICE.md.\n"
        'static const char kShaderSource[] = R"glsl(' + source + ')glsl";\n'
    )
